from polragion.utils.text_sanitizer import html_to_document, ParsedDocument


def _print_document(doc: ParsedDocument | None):
    print("===== Markdown =====")
    print(doc.markdown)
    print("===== Embedding =====")
    print(doc.embedding_text)


def test_text_sanitizer_1() -> None:
    html = """Blabla - more bla.<br/> This is more bla.<br/> and then blabla<span style="font-weight: bold;"> /* Project_ID/WI_Identifier something important. */</span>"""
    document = html_to_document(html)
    _print_document(document)


